[ExtensionOf(formStr(RetailInstanceAttributeValues))]
public final class RetailInstanceAttributeValuesFormGUP_Extension
{
    private boolean globalUnifiedPricingEnabled = FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance());

}

Method.Source:
public void init()
{
    next init();

    if (globalUnifiedPricingEnabled)
    {
        Common commonTable = this.args().record();
        this.setControlVisibility(commonTable);
    }
}

private void setControlVisibility(Common _commonTable)
{
    if (_commonTable.TableId == tableNum(SalesTable))
    {
        SalesTable salesTable = _commonTable as SalesTable;
        boolean allowEdit = this.allowEdit(salesTable);
        ValueTab.enabled(allowEdit);
    }
}

private boolean allowEdit(SalesTable _salesTable)
{
    return _salesTable.SalesType != SalesType::ReturnItem && _salesTable.SalesStatus == SalesStatus::Backorder && _salesTable.MCROrderStopped == NoYes::Yes;
}
